{"l":6688,"g":7,"b":4,"cefr":"B1","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'He suggested ___ to the beach.'","o":["to go","go","going","went"],"a":"going","r":"Efter 'suggest' kommer ing-form: 'suggested going'."},
