{"l":6899,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'gennemsnitlig' på engelsk i 'He's of ___ height'?","o":["perfect","average","unusual","similar"],"a":"average","r":"'Average' = gennemsnitlig."},
{"l":6910,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Most of the class voted for a trip to the zoo, but the teacher chose the science museum because it was free and closer.' Hvorfor valgte læreren museet?","o":["Flest elever ville derhen","Zoologisk have var lukket","Det var gratis og tættere på","Hun er bange for dyr"],"a":"Det var gratis og tættere på","r":"Læreren valgte museet, fordi det var gratis og lå tættere på."},
{"l":6938,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'At our school, pupils ___ wear a uniform, but many do.'","o":["mustn't","haven't to","can't","don't have to"],"a":"don't have to","r":"'Don't have to' betyder, at man ikke er nødt til det. 'Mustn't' betyder, at det er forbudt."},
{"l":6938,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'We have ___ time, so we need to hurry.'","o":["little","few","a few","many"],"a":"little","r":"'Time' kan ikke tælles, så man bruger 'little' = ikke meget. 'Few' bruges med tællelige ord."},
{"l":6948,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'smart' i 'You look very smart in that suit.'?","o":["klog","velklædt","fræk","træt"],"a":"velklædt","r":"Om tøj betyder britisk 'smart' pæn eller velklædt. Det kan også betyde klog, men ikke her."},
{"l":6962,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'anbefale' på engelsk i 'Can you ___ a good book?'?","o":["remember","recognise","recommend","request"],"a":"recommend","r":"'Recommend' = anbefale."},
{"l":6974,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'burde' på engelsk i 'You ___ see a doctor'?","o":["used to","want to","tend to","ought to"],"a":"ought to","r":"'Ought to' = burde."},
{"l":6987,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'temmelig' på engelsk i 'I'm ___ tired'?","o":["rather","rarely","hardly","always"],"a":"rather","r":"'Rather' = temmelig (eller hellere i 'I'd rather')."},
{"l":6999,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'næsten ikke' på engelsk i 'I can ___ hear you'?","o":["easily","hardly","clearly","nearly"],"a":"hardly","r":"'Hardly' = knap nok."},
{"l":7005,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'If he ___ harder, he would get better marks.'","o":["works","will work","worked","has worked"],"a":"worked","r":"Betingelse type 2: if + datid ('worked') og would + verbum."},
{"l":7020,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'If I ___ more time, I would learn to play the guitar.'","o":["have","would have","will have","had"],"a":"had","r":"Betingelse type 2: if + datid, would + verbum. Derfor 'had', ikke 'have'."},
{"l":7030,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Mia's grandfather never threw anything away. When he moved, it took the family three weekends to empty his garage.' Hvad kan man slutte om garagen?","o":["Den var fuld af ting","Den var meget lille","Den var helt ny","Den var tom i forvejen"],"a":"Den var fuld af ting","r":"Han smed aldrig noget ud, og det tog tre weekender at tømme garagen. Den må have været fuld."},
{"l":7050,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'What ___ you do if you found a wallet in the street?'","o":["will","would","did","had"],"a":"would","r":"'If you found' er betingelse type 2, så hovedsætningen skal have 'would'."},
{"l":7065,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'If it ___ so expensive, we would go to the concert.'","o":["isn't","won't be","weren't","hasn't been"],"a":"weren't","r":"Betingelse type 2 om noget uvirkeligt i nutiden: if + datid ('weren't'), would + verbum."},
{"l":7085,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'clumsy' i 'I'm so clumsy; I dropped my plate again'?","o":["doven","sulten","heldig","klodset"],"a":"klodset","r":"'Clumsy' betyder klodset, en der let taber eller vælter ting."},
{"l":7110,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'Could you ___ me to buy milk on the way home?'","o":["remind","remember","memorise","recall"],"a":"remind","r":"'Remind someone to do something' betyder minde nogen om noget. 'Remember' er at huske selv."},
{"l":7130,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'elderly' i 'an elderly couple'?","o":["ancient","young","healthy","friendly"],"a":"young","r":"'Elderly' betyder ældre, og 'young' betyder ung."},
{"l":7140,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'The heavy rain made the path very ___.'","o":["slipping","slipped","slippery","slip"],"a":"slippery","r":"Efter 'very' skal der et tillægsord: 'slippery' betyder glat."},
{"l":7170,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'She ___ a promise never to tell anyone.'","o":["did","took","held","made"],"a":"made","r":"Man siger 'make a promise' på engelsk, ikke 'do a promise'."},
{"l":7190,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad hedder 'tålmodighed' på engelsk?","o":["patience","patients","passion","practice"],"a":"patience","r":"Tålmodighed hedder 'patience'. 'Patients' udtales næsten ens, men betyder patienter."},
{"l":7210,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man høfligt vil takke nej til et tilbud?","o":["Thanks, I'll take it right away.","Thanks, but I think I'll pass.","No, give it to me at once.","Sorry, could you pass it to me?"],"a":"Thanks, but I think I'll pass.","r":"'I'll pass' betyder høfligt nej tak. 'Could you pass it to me' betyder række det til mig."},
{"l":7230,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'The new girl sat alone for the first week. Now she is the one who organises the class trips.' Hvad viser teksten?","o":["Hun er stadig alene","Hun er blevet lærer","Hun er faldet godt til","Hun kan ikke lide klassen"],"a":"Hun er faldet godt til","r":"Først sad hun alene, nu arrangerer hun klassens ture. Hun er altså faldet godt til."},
{"l":7255,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'The plane will ___ off in ten minutes.'","o":["go","put","turn","take"],"a":"take","r":"Når et fly letter, hedder det 'take off'. 'Go off' bruges om en alarm, der går i gang."},
{"l":7280,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'Some pupils love maths, ___ others find it really hard.'","o":["whereas","therefore","unless","despite"],"a":"whereas","r":"'Whereas' betyder hvorimod og viser en kontrast mellem to grupper."},
{"l":7310,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'puzzled' i 'He looked puzzled when he read the question'?","o":["fornærmet","forvirret","fornøjet","forsinket"],"a":"forvirret","r":"'Puzzled' betyder forvirret eller uforstående."},
{"l":7330,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'The match went ahead ___ the heavy rain.'","o":["although","however","despite","even though"],"a":"despite","r":"'Despite' står foran et navneord som 'the heavy rain'. 'Although' og 'even though' skal efterfølges af en hel sætning."},
{"l":7360,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'He's very ___; he always notices when someone is upset.'","o":["sensible","sensational","senseless","sensitive"],"a":"sensitive","r":"'Sensitive' betyder følsom. 'Sensible' er en falsk ven og betyder fornuftig."},
{"l":7380,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad betyder 'hit the hay' i 'I'm exhausted, so I'm going to hit the hay'?","o":["gå i seng","arbejde hårdt","tage en pause","gå en tur"],"a":"gå i seng","r":"'Hit the hay' er et uformelt udtryk for at gå i seng."},
{"l":7395,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'If you ___ me, I would have helped you.'","o":["asked","had asked","have asked","would ask"],"a":"had asked","r":"Betingelse type 3: 'would have helped' kræver førdatid i if-sætningen: 'had asked'."},
{"l":7420,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Although the hotel looked nothing like the photos online, the staff were so kind that we hardly cared.' Hvad var vigtigst for skribenten?","o":["At hotellet lignede billederne","At værelset var billigt","At personalet var venligt","At hotellet lå tæt på stranden"],"a":"At personalet var venligt","r":"Personalet var så venligt, at skribenten næsten var ligeglad med, at hotellet ikke lignede billederne."},
{"l":7455,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man vil vise, at man selv har oplevet det samme som en anden?","o":["I know the sense.","I have the feeling.","I feel you know.","I know the feeling."],"a":"I know the feeling.","r":"'I know the feeling' betyder, at man kender følelsen. 'I have the feeling' betyder, at man har på fornemmelsen."},
{"l":7470,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'You ___ have told her the secret; now everyone knows.'","o":["shouldn't","mustn't","can't","wouldn't"],"a":"shouldn't","r":"'Shouldn't have' bruges til at kritisere noget, der skete. 'Mustn't have' findes ikke i den betydning."},
{"l":7500,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'frequent' i 'frequent visits'?","o":["regular","rare","recent","brief"],"a":"rare","r":"'Frequent' betyder hyppig, og 'rare' betyder sjælden. 'Regular' betyder næsten det samme som 'frequent'."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
